name: Danger Comment

on:
  workflow_run:
    workflows: ["Danger"]
    types:
      - completed

permissions:
  pull-requests: write
  contents: read

jobs:
  danger-comment:
    runs-on: ubuntu-latest
    if: ${{ github.event.workflow_run.event == 'pull_request' && github.event.workflow_run.conclusion == 'success' }}
    steps:
      - name: Download artifact
        uses: actions/github-script@v7
        with:
          script: |
            let allArtifacts = await github.rest.actions.listWorkflowRunArtifacts({
               owner: context.repo.owner,
               repo: context.repo.repo,
               run_id: context.payload.workflow_run.id,
            });
            let matchArtifact = allArtifacts.data.artifacts.filter((artifact) => {
              return artifact.name == "danger_results"
            })[0];
            let download = await github.rest.actions.downloadArtifact({
               owner: context.repo.owner,
               repo: context.repo.repo,
               artifact_id: matchArtifact.id,
               archive_format: 'zip',
            });
            let fs = require('fs');
            fs.writeFileSync(`${process.env.GITHUB_WORKSPACE}/danger_results.zip`, Buffer.from(download.data));

      - name: Unzip artifact
        run: unzip danger_results.zip

      - name: Post comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');

            // Read the markdown file
            const markdownPath = path.join(process.env.GITHUB_WORKSPACE, 'results.md');
            let message = fs.readFileSync(markdownPath, 'utf8');

            // Get the PR number from the workflow run
            const prNumber = context.payload.workflow_run.pull_requests[0].number;

            // Post the comment
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: message
            });
